+      }
+      throw error;
+    }
+  }
+
+  /**
+   * Retrieves full secret information including expiry date.
+   */
+  async getSecretInfo(name: string): Promise<SecretInfo | null> {
+    try {
+      const secret = await this.client.getSecret(name);
+      return {
+        name: secret.name,
